"type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"marketFactory","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"","type":"address"}],"name":"marketIds","outputs":[{"internalType":"bytes32","name":"","type":"bytes32"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"market","type":"address"},{"internalType":"bytes32","name":"marketId","type":"bytes32"}],"name":"registerMarket","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"totalMarkets","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"newFactory","type":"address"}],"name":"updateFactory","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"kind":"dev","methods":{"invalidateMarket(address)":{"details":"Used only for emergency or post-mortem scenarios"},"registerMarket(address,bytes32)":{"details":"Callable only by authorized MarketFactory"}},"version":1},"userdoc":{"kind":"user","methods":{"governance()":{"notice":"Governance authority (DAO / Timelock)"},"invalidateMarket(address)":{"notice":"Explicitly invalidate a market"},"isValidMarket(address)":{"notice":"Market address => validity"},"marketFactory()":{"notice":"Authorized market factory"},"marketIds(address)":{"notice":"Market address => marketId"},"registerMarket(address,bytes32)":{"notice":"Register a newly created market"},"totalMarkets()":{"notice":"Total number of markets ever registered"}},"version":1}},"settings":{"compilationTarget":{"core/MarketRegistry.sol":"MarketRegistry"},"evmVersion":"paris","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[]},"sources":{"core/MarketRegistry.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    MarketRegistry.sol

    PURPOSE
    -------
    Canonical on-chain registry of all valid prediction markets.
    Acts as the single source of truth for:
    - market existence
    - market identity
    - market validity

    DESIGN GUARANTEES
    -----------------
    - Append-only registration (no silent removals)
    - Deterministic lookups
    - Event-sourced for full replay
    - Governance-bounded controls
    - No custody of funds

    TRUST MODEL
    -----------
    - Callers are untrusted
    - Factory contracts are permissioned
    - Governance may pause or invalidate markets explicitly
*/

contract MarketRegistry {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error OnlyFactory();
    error OnlyGovernance();
    error MarketAlreadyRegistered();
    error InvalidMarketAddress();
    error MarketNotRegistered();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event MarketRegistered(
        address indexed market,
        bytes32 indexed marketId
    );

    event MarketInvalidated(
        address indexed market,
        bytes32 indexed marketId
    );

    event FactoryUpdated(address indexed newFactory);

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    /// @notice Governance authority (DAO / Timelock)
    address public governance;

    /// @notice Authorized market factory
    address public marketFactory;

    /// @notice Market address => marketId
    mapping(address => bytes32) public marketIds;

    /// @notice Market address => validity
    mapping(address => bool) public isValidMarket;

    /// @notice Total number of markets ever registered
    uint256 public totalMarkets;

    /*//////////////////////////////////////////////////////////////
                              MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyGovernance() {
        if (msg.sender != governance) revert OnlyGovernance();
        _;
    }

    modifier onlyFactory() {
        if (msg.sender != marketFactory) revert OnlyFactory();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(address _governance, address _marketFactory) {
        require(_governance != address(0), "INVALID_GOVERNANCE");
        require(_marketFactory != address(0), "INVALID_FACTORY");

        governance = _governance;
        marketFactory = _marketFactory;
    }

    /*//////////////////////////////////////////////////////////////
                        GOVERNANCE CONTROLS
    //////////////////////////////////////////////////////////////*/

    function updateFactory(address newFactory)
        external
        onlyGovernance
    {
        require(newFactory != address(0), "INVALID_FACTORY");
        marketFactory = newFactory;
        emit FactoryUpdated(newFactory);
    }

    /*//////////////////////////////////////////////////////////////
                        REGISTRATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Register a newly created market
     * @dev Callable only by authorized MarketFactory
     */
    function registerMarket(address market, bytes32 marketId)
        external
        onlyFactory
    {
        if (market == address(0)) revert InvalidMarketAddress();
        if (isValidMarket[market]) revert MarketAlreadyRegistered();

        isValidMarket[market] = true;
        marketIds[market] = marketId;
        totalMarkets += 1;

        emit MarketRegistered(market, marketId);
    }

    /*//////////////////////////////////////////////////////////////
                        INVALIDATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Explicitly invalidate a market
     * @dev Used only for emergency or post-mortem scenarios
     */
    function invalidateMarket(address market)
        external
        onlyGovernance
    {
        if (!isValidMarket[market]) revert MarketNotRegistered();

        isValidMarket[market] = false;

        emit MarketInvalidated(market, marketIds[market]);
    }

    /*//////////////////////////////////////////////////////////////
                        VIEW FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function isMarket(address market)
        external
        view
        returns (bool)
    {
        return isValidMarket[market];
    }

    function getMarketId(address market)
        external
        view
        returns (bytes32)
    {
        if (!isValidMarket[market]) revert MarketNotRegistered();
        return marketIds[market];
    }
}
