pragma solidity ^0.8.20;

/*
    MarketRegistry.sol

    PURPOSE
    -------
    Canonical on-chain registry of all valid prediction markets.
    Acts as the single source of truth for:
    - market existence
    - market identity
    - market validity

    DESIGN GUARANTEES
    -----------------
    - Append-only registration (no silent removals)
    - Deterministic lookups
    - Event-sourced for full replay
    - Governance-bounded controls
    - No custody of funds

    TRUST MODEL
    -----------
    - Callers are untrusted
    - Factory contracts are permissioned
    - Governance may pause or invalidate markets explicitly
*/

contract MarketRegistry {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error OnlyFactory();
    error OnlyGovernance();
    error MarketAlreadyRegistered();
    error InvalidMarketAddress();
    error MarketNotRegistered();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event MarketRegistered(
        address indexed market,
        bytes32 indexed marketId
    );

    event MarketInvalidated(
        address indexed market,
        bytes32 indexed marketId
    );

    event FactoryUpdated(address indexed newFactory);

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    /// @notice Governance authority (DAO / Timelock)
    address public governance;

    /// @notice Authorized market factory
    address public marketFactory;

    /// @notice Market address => marketId
    mapping(address => bytes32) public marketIds;

    /// @notice Market address => validity
    mapping(address => bool) public isValidMarket;

    /// @notice Total number of markets ever registered
    uint256 public totalMarkets;

    /*//////////////////////////////////////////////////////////////
                              MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyGovernance() {
        if (msg.sender != governance) revert OnlyGovernance();
        _;
    }

    modifier onlyFactory() {
        if (msg.sender != marketFactory) revert OnlyFactory();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(address _governance, address _marketFactory) {
        require(_governance != address(0), "INVALID_GOVERNANCE");
        require(_marketFactory != address(0), "INVALID_FACTORY");

        governance = _governance;
        marketFactory = _marketFactory;
    }

    /*//////////////////////////////////////////////////////////////
                        GOVERNANCE CONTROLS
    //////////////////////////////////////////////////////////////*/

    function updateFactory(address newFactory)
        external
        onlyGovernance
    {
        require(newFactory != address(0), "INVALID_FACTORY");
        marketFactory = newFactory;
        emit FactoryUpdated(newFactory);
    }

    /*//////////////////////////////////////////////////////////////
                        REGISTRATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Register a newly created market
     * @dev Callable only by authorized MarketFactory
     */
    function registerMarket(address market, bytes32 marketId)
        external
        onlyFactory
    {
        if (market == address(0)) revert InvalidMarketAddress();
        if (isValidMarket[market]) revert MarketAlreadyRegistered();

        isValidMarket[market] = true;
        marketIds[market] = marketId;
        totalMarkets += 1;

        emit MarketRegistered(market, marketId);
    }

    /*//////////////////////////////////////////////////////////////
                        INVALIDATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Explicitly invalidate a market
     * @dev Used only for emergency or post-mortem scenarios
     */
    function invalidateMarket(address market)
        external
        onlyGovernance
    {
        if (!isValidMarket[market]) revert MarketNotRegistered();

        isValidMarket[market] = false;

        emit MarketInvalidated(market, marketIds[market]);
    }

    /*//////////////////////////////////////////////////////////////
                        VIEW FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function isMarket(address market)
        external
        view
        returns (bool)
    {
        return isValidMarket[market];
    }

    function getMarketId(address market)
        external
        view
        returns (bytes32)
    {
        if (!isValidMarket[market]) revert MarketNotRegistered();
        return marketIds[market];
    }
}
","keccak256":"0x828dec7cdd789e15a2b3a59a25d666f28e0372925faae9972f9deff8ae7bc310","license":"MIT"},"core/PredictionMarket.sol":{"content":"// File: contracts/core/PredictionMarket.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    PredictionMarket.sol

    PURPOSE
    -------
    Canonical on-chain market contract responsible for:
    - capital custody (escrow only)
    - bet placement and accounting
    - exposure enforcement
    - settlement execution
    - payout distribution

    GUARANTEES (from docs)
    ---------------------
    - Non-custodial: users always interact directly with this contract
    - Deterministic: no off-chain or discretionary logic
    - Event-sourced: every state transition emits events
    - Invariant-driven: exposure, timing, and settlement rules enforced
    - Governance-bounded: emergency controls only via governance

    TRUST MODEL
    -----------
    - Callers are untrusted
    - Oracles resolve outcome externally
    - This contract enforces final settlement only
*/

contract PredictionMarket {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error MarketNotOpen();
    error MarketClosed();
    error MarketAlreadySettled();
    error MarketNotSettled();
    error InvalidOutcome();
    error ExposureExceeded();
    error ZeroAmount();
    error TransferFailed();
    error OnlyGovernance();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event BetPlaced(
        address indexed bettor,
        bool indexed outcome,
        uint256 amount
    );

    event MarketSettled(
        bool outcome,
        uint256 totalYes,
        uint256 totalNo
    );

    event PayoutClaimed(
        address indexed bettor,
        uint256 amount
    );

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    bytes32 public immutable marketId;
    address public immutable creator;
    address public immutable governance;

    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable maxExposure;

    bool public settled;
    bool public finalOutcome;

    uint256 public totalYes;
    uint256 public totalNo;

    mapping(address => uint256) public yesBets;
    mapping(address => uint256) public noBets;

    /*//////////////////////////////////////////////////////////////
                              MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyGovernance() {
        if (msg.sender != governance) revert OnlyGovernance();
        _;
    }

    modifier marketOpen() {
        if (block.timestamp < startTime) revert MarketNotOpen();
        if (block.timestamp >= endTime) revert MarketClosed();
        _;
    }

    modifier notSettled() {
        if (settled) revert MarketAlreadySettled();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(
        bytes32 _marketId,
        address _creator,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _maxExposure,
        address _governance
    ) {
        require(_creator != address(0), "INVALID_CREATOR");
        require(_governance != address(0), "INVALID_GOVERNANCE");
        require(_endTime > _startTime, "INVALID_TIME");

        marketId = _marketId;
        creator = _creator;
        startTime = _startTime;
        endTime = _endTime;
        maxExposure = _maxExposure;
        governance = _governance;
    }

    /*//////////////////////////////////////////////////////////////
                          BETTING LOGIC
    //////////////////////////////////////////////////////////////*/

    function betYes() external payable marketOpen notSettled {
        _placeBet(true, msg.value);
    }

    function betNo() external payable marketOpen notSettled {
        _placeBet(false, msg.value);
    }

    function _placeBet(bool outcome, uint256 amount) internal {
        if (amount == 0) revert ZeroAmount();

        uint256 newExposure = totalYes + totalNo + amount;
        if (newExposure > maxExposure) revert ExposureExceeded();

        if (outcome) {
            yesBets[msg.sender] += amount;
            totalYes += amount;
        } else {
            noBets[msg.sender] += amount;
            totalNo += amount;
        }

        emit BetPlaced(msg.sender, outcome, amount);
    }

    /*//////////////////////////////////////////////////////////////
                        SETTLEMENT LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Settle the market with final outcome
     * @dev Called by governance-controlled settlement engine
     */
    function settle(bool outcome) external onlyGovernance notSettled {
        settled = true;
        finalOutcome = outcome;

        emit MarketSettled(outcome, totalYes, totalNo);
    }

    /*//////////////////////////////////////////////////////////////
                          CLAIM LOGIC
    //////////////////////////////////////////////////////////////*/

    function claim() external {
        if (!settled) revert MarketNotSettled();

        uint256 payout;
        uint256 pool = totalYes + totalNo;

        if (finalOutcome) {
            uint256 stake = yesBets[msg.sender];
            if (stake == 0) revert ZeroAmount();
            yesBets[msg.sender] = 0;
            payout = (stake * pool) / totalYes;
        } else {
            uint256 stake = noBets[msg.sender];
            if (stake == 0) revert ZeroAmount();
            noBets[msg.sender] = 0;
            payout = (stake * pool) / totalNo;
        }

        (bool ok, ) = msg.sender.call{value: payout}("");
        if (!ok) revert TransferFailed();

        emit PayoutClaimed(msg.sender, payout);
    }

    /*//////////////////////////////////////////////////////////////
                          VIEW HELPERS
    //////////////////////////////////////////////////////////////*/

    function getTotals() external view returns (uint256 yes, uint256 no) {
        return (totalYes, totalNo);
    }

    function getUserPosition(address user)
        external
        view
        returns (uint256 yes, uint256 no)
    {
        return (yesBets[user], noBets[user]);
    }
}
","keccak256":"0x06bcd3a98c492a6d619d489352df46312c63399c46b1da545cf68658311addb7","license":"MIT"},"core/SettlementEngine.sol":{"content":"// File: contracts/core/SettlementEngine.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    SettlementEngine.sol

    PURPOSE
    -------
    Canonical settlement coordinator that bridges:
    - decentralized oracle consensus
    - final market settlement execution

    This contract:
    - does NOT decide outcomes
    - does NOT perform off-chain computation
    - ONLY enforces finality after oracle consensus

    GUARANTEES (from docs)
    ---------------------
    - Deterministic execution
    - Governance-bounded authority
    - Event-sourced settlements
    - No custody of funds
    - No discretionary override except via governance

    TRUST MODEL
    -----------
    - Oracle network is economically trusted
    - Governance is slow, bounded, and auditable
*/

import {MarketRegistry} from "./MarketRegistry.sol";
import {PredictionMarket} from "./PredictionMarket.sol";

contract SettlementEngine {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error OnlyOracleConsensus();
    error OnlyGovernance();
    error InvalidMarket();
    error MarketAlreadySettled();
    error OracleOutcomeMissing();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event MarketSettlementExecuted(
        address indexed market,
        bool outcome
    );

    event OracleConsensusSet(address indexed oracleConsensus);

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    /// @notice Governance authority (DAO / Timelock)
    address public governance;

    /// @notice Authorized oracle consensus contract
    address public oracleConsensus;

    /// @notice Market registry
    MarketRegistry public immutable marketRegistry;

    /*//////////////////////////////////////////////////////////////
                              MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyOracleConsensus() {
        if (msg.sender != oracleConsensus) revert OnlyOracleConsensus();
        _;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert OnlyGovernance();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(
        address _governance,
        address _oracleConsensus,
        address _marketRegistry
    ) {
        require(_governance != address(0), "INVALID_GOVERNANCE");
        require(_oracleConsensus != address(0), "INVALID_ORACLE");
        require(_marketRegistry != address(0), "INVALID_REGISTRY");

        governance = _governance;
        oracleConsensus = _oracleConsensus;
        marketRegistry = MarketRegistry(_marketRegistry);
    }

    /*//////////////////////////////////////////////////////////////
                        GOVERNANCE CONTROLS
    //////////////////////////////////////////////////////////////*/

    function updateOracleConsensus(address newOracleConsensus)
        external
        onlyGovernance
    {
        require(newOracleConsensus != address(0), "INVALID_ORACLE");
        oracleConsensus = newOracleConsensus;
        emit OracleConsensusSet(newOracleConsensus);
    }

    /*//////////////////////////////////////////////////////////////
                        SETTLEMENT EXECUTION
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Execute settlement after oracle consensus
     * @dev Callable only by authorized oracle consensus contract
     */
    function settleMarket(
        address market,
        bool outcome
    ) external onlyOracleConsensus {
        if (!marketRegistry.isValidMarket(market)) revert InvalidMarket();

        PredictionMarket pm = PredictionMarket(market);

        if (pm.settled()) revert MarketAlreadySettled();

        // Execute settlement
        pm.settle(outcome);

        emit MarketSettlementExecuted(market, outcome);
    }

    /*//////////////////////////////////////////////////////////////
                        GOVERNANCE OVERRIDE (RARE)
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Governance-triggered settlement override
     * @dev Only for catastrophic oracle failure
     */
    function governanceSettleMarket(
        address market,
        bool outcome
    ) external onlyGovernance {
        if (!marketRegistry.isValidMarket(market)) revert InvalidMarket();

        PredictionMarket pm = PredictionMarket(market);

        if (pm.settled()) revert MarketAlreadySettled();

        pm.settle(outcome);

        emit MarketSettlementExecuted(market, outcome);
    }
}

