// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    PredictionMarket.sol

    PURPOSE
    -------
    Canonical on-chain market contract responsible for:
    - capital custody (escrow only)
    - bet placement and accounting
    - exposure enforcement
    - settlement execution
    - payout distribution

    GUARANTEES (from docs)
    ---------------------
    - Non-custodial: users always interact directly with this contract
    - Deterministic: no off-chain or discretionary logic
    - Event-sourced: every state transition emits events
    - Invariant-driven: exposure, timing, and settlement rules enforced
    - Governance-bounded: emergency controls only via governance

    TRUST MODEL
    -----------
    - Callers are untrusted
    - Oracles resolve outcome externally
    - This contract enforces final settlement only
*/

contract PredictionMarket {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error MarketNotOpen();
    error MarketClosed();
    error MarketAlreadySettled();
    error MarketNotSettled();
    error InvalidOutcome();
    error ExposureExceeded();
    error ZeroAmount();
    error TransferFailed();
    error OnlyGovernance();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event BetPlaced(
        address indexed bettor,
        bool indexed outcome,
        uint256 amount
    );

    event MarketSettled(
        bool outcome,
        uint256 totalYes,
        uint256 totalNo
    );

    event PayoutClaimed(
        address indexed bettor,
        uint256 amount
    );

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    bytes32 public immutable marketId;
    address public immutable creator;
    address public immutable governance;

    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable maxExposure;

    bool public settled;
    bool public finalOutcome;

    uint256 public totalYes;
    uint256 public totalNo;

    mapping(address => uint256) public yesBets;
    mapping(address => uint256) public noBets;

    /*//////////////////////////////////////////////////////////////
                              MODIFIERS
    //////////////////////////////////////////////////////////////*/

    modifier onlyGovernance() {
        if (msg.sender != governance) revert OnlyGovernance();
        _;
    }

    modifier marketOpen() {
        if (block.timestamp < startTime) revert MarketNotOpen();
        if (block.timestamp >= endTime) revert MarketClosed();
        _;
    }

    modifier notSettled() {
        if (settled) revert MarketAlreadySettled();
        _;
    }

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(
        bytes32 _marketId,
        address _creator,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _maxExposure,
        address _governance
    ) {
        require(_creator != address(0), "INVALID_CREATOR");
        require(_governance != address(0), "INVALID_GOVERNANCE");
        require(_endTime > _startTime, "INVALID_TIME");

        marketId = _marketId;
        creator = _creator;
        startTime = _startTime;
        endTime = _endTime;
        maxExposure = _maxExposure;
        governance = _governance;
    }

    /*//////////////////////////////////////////////////////////////
                          BETTING LOGIC
    //////////////////////////////////////////////////////////////*/

    function betYes() external payable marketOpen notSettled {
        _placeBet(true, msg.value);
    }

    function betNo() external payable marketOpen notSettled {
        _placeBet(false, msg.value);
    }

    function _placeBet(bool outcome, uint256 amount) internal {
        if (amount == 0) revert ZeroAmount();

        uint256 newExposure = totalYes + totalNo + amount;
        if (newExposure > maxExposure) revert ExposureExceeded();

        if (outcome) {
            yesBets[msg.sender] += amount;
            totalYes += amount;
        } else {
            noBets[msg.sender] += amount;
            totalNo += amount;
        }

        emit BetPlaced(msg.sender, outcome, amount);
    }

    /*//////////////////////////////////////////////////////////////
                        SETTLEMENT LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Settle the market with final outcome
     * @dev Called by governance-controlled settlement engine
     */
    function settle(bool outcome) external onlyGovernance notSettled {
        settled = true;
        finalOutcome = outcome;

        emit MarketSettled(outcome, totalYes, totalNo);
    }

    /*//////////////////////////////////////////////////////////////
                          CLAIM LOGIC
    //////////////////////////////////////////////////////////////*/

    function claim() external {
        if (!settled) revert MarketNotSettled();

        uint256 payout;
        uint256 pool = totalYes + totalNo;

        if (finalOutcome) {
            uint256 stake = yesBets[msg.sender];
            if (stake == 0) revert ZeroAmount();
            yesBets[msg.sender] = 0;
            payout = (stake * pool) / totalYes;
        } else {
            uint256 stake = noBets[msg.sender];
            if (stake == 0) revert ZeroAmount();
            noBets[msg.sender] = 0;
            payout = (stake * pool) / totalNo;
        }

        (bool ok, ) = msg.sender.call{value: payout}("");
        if (!ok) revert TransferFailed();

        emit PayoutClaimed(msg.sender, payout);
    }

    /*//////////////////////////////////////////////////////////////
                          VIEW HELPERS
    //////////////////////////////////////////////////////////////*/

    function getTotals() external view returns (uint256 yes, uint256 no) {
        return (totalYes, totalNo);
    }

    function getUserPosition(address user)
        external
        view
        returns (uint256 yes, uint256 no)
    {
        return (yesBets[user], noBets[user]);
    }
}
","keccak256":"0x06bcd3a98c492a6d619d489352df46312c63399c46b1da545cf68658311addb7","license":"MIT"},"rwa/OutcomeWrapper.sol":{"content":"// File: contracts/rwa/OutcomeWrapper.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    OutcomeWrapper.sol

    PURPOSE
    -------
    Bridges prediction market outcomes into composable ERC20-style
    representations usable across DeFi, RWAs, and cross-chain systems.

    This contract:
    - wraps finalized market outcomes
    - creates canonical outcome tokens (YES / NO)
    - enforces single-mint semantics
    - guarantees settlement correctness

    CRITICAL DESIGN NOTES (from docs)
    ---------------------------------
    - Outcomes MUST be finalized on-chain
    - No speculative minting
    - No retroactive changes
    - No governance override after mint

    TRUST MODEL
    -----------
    - Market settlement is trusted input
    - Governance has NO authority after finalization
*/

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {MarketRegistry} from "../core/MarketRegistry.sol";
import {PredictionMarket} from "../core/PredictionMarket.sol";

contract OutcomeWrapper {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error MarketNotFinalized();
    error MarketAlreadyWrapped();
    error InvalidMarket();
    error ZeroAddress();
    error ZeroAmount();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    event OutcomeWrapped(
        address indexed market,
        address yesToken,
        address noToken
    );

    /*//////////////////////////////////////////////////////////////
                              STORAGE
    //////////////////////////////////////////////////////////////*/

    MarketRegistry public immutable marketRegistry;

    struct WrappedOutcome {
        address yesToken;
        address noToken;
        bool exists;
    }

    /// @notice Market address => wrapped outcome tokens
    mapping(address => WrappedOutcome) public wrappedOutcomes;

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    constructor(address _marketRegistry) {
        if (_marketRegistry == address(0)) revert ZeroAddress();
        marketRegistry = MarketRegistry(_marketRegistry);
    }

    /*//////////////////////////////////////////////////////////////
                        WRAPPING LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Wrap a finalized market into ERC20 outcome tokens
     * @dev Can be called permissionlessly AFTER settlement
     */
    function wrapOutcome(address market)
        external
        returns (address yesToken, address noToken)
    {
        if (!marketRegistry.isValidMarket(market))
            revert InvalidMarket();

        if (wrappedOutcomes[market].exists)
            revert MarketAlreadyWrapped();

        PredictionMarket pm = PredictionMarket(market);

        if (!pm.settled()) revert MarketNotFinalized();

        // Deploy outcome tokens
        yesToken = address(
            new OutcomeToken(
                _tokenName(market, "YES"),
                _tokenSymbol(market, "YES"),
                market,
                true
            )
        );

        noToken = address(
            new OutcomeToken(
                _tokenName(market, "NO"),
                _tokenSymbol(market, "NO"),
                market,
                false
            )
        );

        wrappedOutcomes[market] = WrappedOutcome({
            yesToken: yesToken,
            noToken: noToken,
            exists: true
        });

        emit OutcomeWrapped(market, yesToken, noToken);
    }

    /*//////////////////////////////////////////////////////////////
                        VIEW HELPERS
    //////////////////////////////////////////////////////////////*/

    function getOutcomeTokens(address market)
        external
        view
        returns (address yesToken, address noToken)
    {
        WrappedOutcome memory w = wrappedOutcomes[market];
        if (!w.exists) revert InvalidMarket();
        return (w.yesToken, w.noToken);
    }

    function _tokenName(address market, string memory side)
        internal
        pure
        returns (string memory)
    {
        return string(
            abi.encodePacked("Outcome ", side, " @ ", _toHex(market))
        );
    }

    function _tokenSymbol(address market, string memory side)
        internal
        pure
        returns (string memory)
    {
        return string(
            abi.encodePacked(side, "-", _shortHex(market))
        );
    }

    function _toHex(address a) internal pure returns (string memory) {
        return _shortHex(a);
    }

    function _shortHex(address a) internal pure returns (string memory) {
        bytes20 data = bytes20(a);
        bytes memory out = new bytes(6);
        for (uint256 i = 0; i < 3; i++) {
            out[i * 2] = _hexChar(uint8(data[i] >> 4));
            out[i * 2 + 1] = _hexChar(uint8(data[i] & 0x0f));
        }
        return string(out);
    }

    function _hexChar(uint8 c) internal pure returns (bytes1) {
        return c < 10 ? bytes1(c + 48) : bytes1(c + 87);
    }
}

/*//////////////////////////////////////////////////////////////
                    INTERNAL OUTCOME TOKEN
//////////////////////////////////////////////////////////////*/

contract OutcomeToken is ERC20 {
    address public immutable market;
    bool public immutable outcomeSide;
    bool private minted;

    error AlreadyMinted();
    error MarketNotSettled();

    constructor(
        string memory name_,
        string memory symbol_,
        address _market,
        bool _outcomeSide
    ) ERC20(name_, symbol_) {
        market = _market;
        outcomeSide = _outcomeSide;
    }

    /**
     * @notice Mint tokens based on user position
     * @dev One-time mint per market side
     */
    function mint(address to, uint256 amount) external {
        if (minted) revert AlreadyMinted();

        PredictionMarket pm = PredictionMarket(market);
        if (!pm.settled()) revert MarketNotSettled();

        minted = true;
        _mint(to, amount);
    }
}
